"use client";

import { useState } from "react";

export default function Modal() {
  const [open, setOpen] = useState(false);

  return (
    <>
      <button onClick={() => setOpen(true)}>
        Open Modal
      </button>

      {open && (
        <div>
          <button onClick={() => setOpen(false)}>
            Close
          </button>
        </div>
      )}
    </>
  );
}

